import numpy as np

def unbiased_variance(sample):
    return np.var(sample, ddof=1)

data = np.array([10, 12, 14, 16, 18, 20])
print(unbiased_variance(data))

import numpy as np
from scipy.optimize import minimize_scalar

k, n = 37, 100

def log_likelihood_bernoulli(p):
    return k * np.log(p) + (n - k) * np.log(1 - p)

def neg_log_likelihood_bernoulli(p):
    return -log_likelihood_bernoulli(p)

result = minimize_scalar(neg_log_likelihood_bernoulli, bounds=(1e-6, 1 - 1e-6), method="bounded")
print(result.x)  # close to k/n = 0.37
